//! `omr-model`: the shared vocabulary of the OMR engine (spec §4.3).
//!
//! This crate holds identifiers, units, fixed-point quantities, mark classes and states,
//! question responses, the exception model with the Appendix A catalogue, and the engine
//! manifest. By rule R2 (key-blindness, §4.3) it contains **no** answer-key, policy or score
//! types: those live in `omr-scoring` and `omr-outcomes`, which recognition never links.
#![forbid(unsafe_code)]
#![warn(missing_docs)]

/// The Appendix A exception catalogue (generated by `scripts/gen_exception_catalogue.py`).
pub mod catalogue;
pub mod exceptions;
pub mod fixed;
pub mod geom;
pub mod idgrid;
pub mod ids;
pub mod manifest;
pub mod marks;

pub use exceptions::{Exception, ExceptionDef, Scope, Severity};
pub use fixed::{Darkness, LogitMilli};
pub use geom::{PointMm, PointPx, RectMm};
pub use idgrid::{ColumnState, IdColumnRead, IdGridRead};
pub use ids::{BookletSerial, ExamId, FormCode, PageNo, StudentKey, TemplateRevision};
pub use manifest::{BatchContext, EngineManifest};
pub use marks::{CancelMode, MarkClass, QuestionOutcome, Response};
